// Placeholder Error Utility Generated By Claude

// Thrown by services when input breaks a business rule (e.g. an empty title).
// Controllers catch it and respond with 400 and its message.
export class ValidationError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'ValidationError';
  }
}

// Caught errors are typed `unknown` in TypeScript; this gets a loggable message.
// Excluded from coverage: only reachable by unexpected errors no controller
// caught. This is purely defensive code.
/* v8 ignore start -- @preserve */
export function getErrorMessage(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}
/* v8 ignore stop -- @preserve */
